import {tracks} from '../learn/content.mjs';
import {catalog} from '../concepts/catalog.mjs';
import {names} from './config.mjs';
const base=new URL('../',import.meta.url),norm=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
export function library(en){const l=en?'en':'es',rows=[],row=(kind,name,path,words='')=>rows.push({kind,name,path:new URL(path,base).href,words});
 names.forEach((n,i)=>row('lab',n[+en],'studio/lab.html?stage='+i+'&lang='+l,n.join(' ')+' engranaje piñones piñonería gears transmisión'+(i===5?' embrague despiece sincronizadores sincronizador torque manguito clutch synchronizer gearbox exploded':'')));
 for(const t of tracks)for(const a of t.lessons)row('course',a.title[l],'learn/index.html?track='+t.id+'&lesson='+a.id+'&lang='+l,Object.values(t.name).join(' ')+' '+Object.values(a.title).join(' '));
 for(const [id,c] of Object.entries(catalog))row('lab',c.title,'concepts/index.html?id='+id,id+' '+c.insight);
 for(const [n,p,k,w] of [['Taller automotriz','autos/index.html','course','carros engine motor'],['Mecánica de bicicletas','bikes/index.html','course','ciclas bikes'],['Física y mecatrónica','index.html#curso','course','fuerzas electromecánica PLC'],['Cambio trasero','bikes/shifting.html','lab','cassette desviador guaya'],['PLC · comparación de ciclos','machines/comparison.html','lab','ladder neumática']])row(k,n,p,w);
 return rows}
export function search(button,en=false){const all=library(en),t=(a,b)=>en?b:a,d=document.createElement('dialog');d.className='ml-find';d.setAttribute('aria-label',t('Buscar en la academia','Search the academy'));d.innerHTML='<form method="dialog"><button aria-label="'+t('Cerrar','Close')+'">Esc ×</button></form><input type="search" autofocus><div class="ml-filters"></div><p role="status"></p><div class="ml-results"></div>';document.body.append(d);const input=d.querySelector('input'),list=d.querySelector('.ml-results');input.placeholder=t('Busca una lección o un mecanismo…','Find a lesson or mechanism…');input.setAttribute('aria-label',input.placeholder);let kind='all';for(const [id,label] of [['all',t('Todo','All')],['course',t('Cursos','Courses')],['lab',t('Laboratorios','Labs')]]){const b=document.createElement('button');b.textContent=label;b.dataset.kind=id;d.querySelector('.ml-filters').append(b);b.onclick=()=>{kind=id;render()}}
 function render(){const terms=norm(input.value).trim().split(/\s+/),items=all.filter(r=>(kind==='all'||r.kind===kind)&&terms.every(w=>norm(r.name+' '+r.words).includes(w))).sort((a,b)=>Number(norm(b.name).includes(terms.join(' ')))-Number(norm(a.name).includes(terms.join(' '))));list.replaceChildren();for(const r of items){const a=document.createElement('a');a.href=r.path;a.textContent=r.name;const small=document.createElement('small');small.textContent=r.kind==='lab'?'LAB':t('CURSO','COURSE');a.prepend(small);list.append(a)}d.querySelector('[role=status]').textContent=items.length+' '+t('resultados','results');d.querySelectorAll('[data-kind]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.kind===kind)))}
 input.oninput=render;function open(){if(!d.open)d.showModal();input.focus();render()}button.onclick=open;document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();open()}});d.addEventListener('keydown',e=>{const a=[...list.children],i=a.indexOf(document.activeElement);if((e.key==='ArrowDown'||e.key==='ArrowUp')&&a.length){e.preventDefault();a[(i+(e.key==='ArrowDown'?1:-1)+a.length)%a.length].focus()}if(e.key==='Enter'&&document.activeElement===input&&a[0]){e.preventDefault();a[0].click()}});d.onclick=e=>{if(e.target===d)d.close()};return d}
